import { describe, it, expect, vi } from 'vitest';
import UserPreferences from './UserPreferences';
import { cookies, headers } from 'next/headers';

// Mock next/headers
vi.mock('next/headers', () => ({
  cookies: vi.fn(),
  headers: vi.fn(),
}));

describe('UserPreferences', () => {
  it('renders with default theme and unknown language when no cookies/headers present', async () => {
    (cookies as any).mockResolvedValue({
      get: () => undefined,
    });
    (headers as any).mockResolvedValue({
      get: () => null,
    });

    const result = await UserPreferences();
    expect(result).toBeDefined();
  });

  it('renders with specific theme and language', async () => {
    (cookies as any).mockResolvedValue({
      get: (name: string) => name === 'theme' ? { value: 'dark' } : undefined,
    });
    (headers as any).mockResolvedValue({
      get: (name: string) => name === 'accept-language' ? 'fr-FR' : null,
    });

    const result = await UserPreferences();
    expect(result).toBeDefined();
  });
});
